def merge_weighted_intervals(intervals: list[tuple[int, int, int]]) -> list[tuple[int, int, int]]:
    valid_intervals = []
    for start, end, weight in intervals:
        if start < end and weight != 0:
            valid_intervals.append((start, end, weight))
    if not valid_intervals:
        return []
    points = set()
    for start, end, _ in valid_intervals:
        points.add(start)
        points.add(end)
    sorted_points = sorted(points)
    segments = []
    active_weights = {}
    i = 0
    n = len(sorted_points)
    while i < n - 1:
        current_start = sorted_points[i]
        current_end = sorted_points[i + 1]
        total_weight = 0
        for start, end, weight in valid_intervals:
            if start <= current_start and current_end <= end:
                total_weight += weight
        if total_weight != 0:
            segments.append((current_start, current_end, total_weight))
        i += 1
    if not segments:
        return []
    merged = [segments[0]]
    for current_start, current_end, current_weight in segments[1:]:
        last_start, last_end, last_weight = merged[-1]
        if last_end == current_start and last_weight == current_weight:
            merged[-1] = (last_start, current_end, last_weight)
        else:
            merged.append((current_start, current_end, current_weight))
    return merged

def simulate_token_bucket(capacity: int, rate_per_sec: int, events: list[tuple[int, int]]) -> list[bool]:
    if not events:
        return []
    nano_capacity = capacity * 1000000000
    tokens = nano_capacity
    prev_ns = 0
    results = []
    for timestamp_ns, cost_tokens in events:
        delta_ns = timestamp_ns - prev_ns
        tokens += delta_ns * rate_per_sec
        if tokens > nano_capacity:
            tokens = nano_capacity
        prev_ns = timestamp_ns
        nano_cost = cost_tokens * 1000000000
        if tokens >= nano_cost:
            tokens -= nano_cost
            results.append(True)
        else:
            results.append(False)
    return results

import heapq

def shortest_path_at_most_k_edges(n: int, edges: list[tuple[int, int, int]], src: int, dst: int, max_edges: int) -> int:
    if src == dst:
        return 0
    if max_edges == 0:
        return -1
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
    heap = []
    heapq.heappush(heap, (0, src, 0))
    visited = {}
    while heap:
        current_weight, u, edges_used = heapq.heappop(heap)
        if u == dst:
            return current_weight
        if edges_used >= max_edges:
            continue
        if (u, edges_used) in visited and visited[u, edges_used] < current_weight:
            continue
        visited[u, edges_used] = current_weight
        for v, w in adj[u]:
            new_weight = current_weight + w
            new_edges = edges_used + 1
            if new_edges <= max_edges:
                heapq.heappush(heap, (new_weight, v, new_edges))
    return -1

import hashlib

def consistent_hash_assign(nodes: list[str], vnodes: int, keys: list[str]) -> dict[str, str]:
    if not nodes or vnodes <= 0:
        return {}
    unique_nodes = list(dict.fromkeys(nodes))
    ring = []
    for node in unique_nodes:
        for v in range(vnodes):
            token = int.from_bytes(hashlib.sha256(f'{node}#{v}'.encode('utf-8')).digest()[:8], 'big')
            ring.append((token, node))
    ring.sort()
    result = {}
    for k in keys:
        kt = int.from_bytes(hashlib.sha256(k.encode('utf-8')).digest()[:8], 'big')
        for token, node in ring:
            if token >= kt:
                result[k] = node
                break
        else:
            if ring:
                result[k] = ring[0][1]
    return result
